INSERT OR IGNORE INTO catalogue_pages (id, position, code, name, layout, header_image, teaser_images, header_text, teaser_text, special_text, min_level, open_to_club, club_only) VALUES
    (1, 1, 'Purse', 'Purse', 'ctlg_purse', 'catal_fp_header', 'catal_fp_pic4', 'Need some furni for your Habbo room? Well, you''re in the right place! This Catalogue is packed FULL of funky Furni, just click the tabs on the right to browse', 'Need some Funky Furni for your Habbo', '', 0, FALSE, FALSE),
    (2, 2, 'Frontpage', 'Frontpage', 'ctlg_frontpage2', 'catal_fp_header', 'catal_fp_pic4,catal_fp_pic5', 'Need some Furni for your Habbo room?  Well, you?re in the right place!  This Catalogue is packed FULL of funky Furni, just click the tabs on the right to browse.<br><br>We regularly add and remove Furni, so check back regularly for new items.', '', 'Need some Funky Furni for your Habbo room?', 0, FALSE, FALSE),
    (3, 3, 'Collectables', 'Collectables', 'ctlg_collectibles', 'catalog_collectibles_headline1', 'collectible_page', 'Collect your way to the riches! Collectables are special furniture sold only for a limited period of time. They cost a wee bit more, but make it up with an amazing trade value.', 'Find out what the latest collectible is >>', '', 0, FALSE, FALSE),
    (5, 5, 'no rares', 'Rare', 'ctlg_norares', 'catalog_rares_headline1', 'ctlg_norare_char1', 'There isn''t a rare item to buy at the moment, but it''s coming soon! Please don''t email us about it - we''re keeping it secret...<br>', '', '', 7, FALSE, FALSE),
    (6, 6, 'Rare', 'Rare', 'ctlg_productpage1', 'catalog_rares_headline1', '', 'It''s Spring, and it''s the best time to stock up on Parasols! Go get your Green Parasol Now!:', '', 'Only for 2 weeks!!!', 0, FALSE, FALSE),
    (7, 7, 'Spaces', 'Spaces', 'ctlg_spaces', 'catalog_spaces_headline1', '', 'Are your walls looking a little grey?  What you need is a splash of paint and this is the place to get it!  <br><br>A splash of colour on the walls and a nice carpet can make all the difference. Use our virtual room below to test out the combinations before you buy.', '', '', 0, FALSE, FALSE),
    (9, 9, 'Pet Accesories', 'Pet Accesories', 'ctlg_layout2', 'catalog_pet_headline2', 'ctlg_pet_teaser1', 'You''ll need to take care of your pet to keep it happy and healthy. This section of the Catalogue has EVERYTHING you?ll need to satisfy your pet?s needs.', 'Click on the item you want for more information.', 'You''ll have to share it!', 0, FALSE, FALSE),
    (10, 10, 'Alhambra', 'Alhambra', 'ctlg_layout2', 'catalog_alh_headline2', 'catalog_alh_teaser2', 'The Palace of Alhambra has appeared and with it this exotic and beautifully crafted range of Arabian Furni. Luxury seating and gourmet food combine to make your room sparkle with riches.', 'Click on an item to see more details', '', 0, FALSE, FALSE),
    (11, 11, 'Area', 'Area', 'ctlg_layout2', 'catalog_area_headline1', 'catalog_area_teaser1', 'Introducing the Area Collection...  Clean, chunky lines set this collection apart as a preserve of the down-to-earth Habbo. It''s beautiful in its simplicity, and welcoming to everyone.', 'Click on the item you want for more information.', '2: Beautiful in it''s simplicity!', 0, FALSE, FALSE),
    (12, 12, 'Accessories', 'Accessories', 'ctlg_layout2', 'catalog_extra_headline1', 'catalog_extra_teaser1', 'Is your room missing something?  Well, now you can add the finishing touches that express your true personality. And don''t forget, like everything else, these accessories can be moved about to suit your mood.', 'Click on the item you want for more information.', '2: I love my rabbit...', 0, FALSE, FALSE),
    (13, 13, 'Asian', 'Asian', 'ctlg_layout2', 'catalog_asian_headline1', 'catalog_asian_teaser1', 'Dit pure haandwerk uit de eeuwenoude oosterse pixeltraditie brengt balans in elk Habbointerieur. Jin en Yang vloeien samen met Feng en Shui in een uitgebalanceerde collectie meubi. ', 'Click on the item you want for more information.', '2: Oh, look there! Is Mulan the girl of Disney xD', 0, FALSE, FALSE),
    (14, 14, 'Bathroom', 'Bathroom', 'ctlg_layout2', 'catalog_bath_headline1', 'catalog_bath_teaser1', 'Introducing the Bathroom Collection...  Have some fun with the cheerful bathroom collection. Give yourself and your guests somewhere to freshen up - vital if you want to avoid nasty niffs. Put your loo in a corner though...', 'Click on the item you want for more information.', '2: Every Habbo needs one!', 0, FALSE, FALSE),
    (15, 15, 'Candy', 'Candy', 'ctlg_layout2', 'catalog_candy_headline1', 'catalog_candy_teaser1', 'Introducing the Candy Collection...  Candy combines the cool, clean lines of the Mode collection with a softer, more soothing style. It''s urban sharpness with a hint of the feminine.', 'Click on the item you want for more information.', '2: Relax! It''s faux-fur.', 0, FALSE, FALSE),
    (17, 17, 'Flags', 'Flags', 'ctlg_layout2', 'catalog_flags_headline1', 'catalog_flags_teaser1', 'If you''re feeling patriotic, get a flag to prove it. Our finest cloth flags will brighten up the dullest walls.', 'Click on the item you want for more information.', '2: Flag this section for later!', 0, FALSE, FALSE),
    (18, 18, 'Gallery', 'Gallery', 'ctlg_layout2', 'catalog_gallery_headline1', 'catalog_posters_teaser1', 'Adorn your walls with wondrous works of art, posters, plaques and wall hangings. We have items to suit all tastes, from kitsch to cool, traditional to modern.', 'Click on the item you want for more information.', '2: Brighten up your walls!', 0, FALSE, FALSE),
    (19, 19, 'Glass', 'Glass', 'ctlg_layout2', 'catalog_glass_headline1', 'catalog_glass_teaser1', 'Glass: Habbo Hotels exclusive furni line made from plexiglass, in different colors! Buy here your furni for a modern lounge!', 'Click on the item you want for more information.', '2: Oh My God, it''s transparant!', 0, FALSE, FALSE),
    (20, 20, 'Gothic', 'Gothic', 'ctlg_layout2', 'catalog_gothic_headline1', 'catalog_gothic_teaser1', 'The Gothic section is full of medieval looking Furni. Check back for additions to this section as there are still some unreleased items to come!', 'Click on the item you want for more information.', 'Gothic is my style.', 0, FALSE, FALSE),
    (21, 21, 'Grunge', 'Grunge', 'ctlg_layout2', 'catalog_gru_headline1', 'catalog_gru_teaser', 'Introducing the Grunge Range. Alternative Habbos with alternative style or rebellious students with a point to prove. The Grunge range will get your bedroom looking just the way you like it - organised, neat and tidy!', 'New! Flaming Barrels out now!', '', 0, FALSE, FALSE),
    (22, 22, 'Habbo Exchange', 'Habbo Exchange', 'ctlg_layout2', 'catalog_bank_headline1', 'catalog_bank_teaser', 'The Habbo Exchange is where you can convert your Habbo Credits into a tradable currency. You can use this tradable currency to exchange Habbo Credits for Furni!', 'Click on an item to see more details', 'Refundable goods!', 0, FALSE, FALSE),
    (23, 23, 'Habbowood', 'Habbowood', 'ctlg_layout2', 'catalog_limited_headline1', 'catalog_limited_teaser1', 'Exclusive: the new Habbowood furni, collect them all!', 'Click on the item you want for more information.', '1: Light, Camera, Action!', 0, FALSE, FALSE),
    (24, 24, 'Iced', 'Iced', 'ctlg_layout2', 'catalog_iced_headline1', 'catalog_iced_teaser1', 'Introducing the Iced Collection...  For the Habbo who needs no introduction. It''s so chic, it says everything and nothing. It''s a blank canvas, let your imagination to run wild!', 'Click on the item you want for more information.', '2: These chairs are so comfy.', 0, FALSE, FALSE),
    (25, 25, 'Japanese', 'Japanese', 'ctlg_layout2', 'catalog_jap_headline2', 'catalog_jap_teaser3', 'Here you can find the new Japanese furni! Get them now!', 'Click on the item you want for more information.', '1: Brand new furni!', 0, FALSE, FALSE),
    (26, 26, 'Lodge', 'Lodge', 'ctlg_layout2', 'catalog_lodge_headline1', 'catalog_lodge_teaser1', 'Introducing the Lodge Collection...  Do you appreciate the beauty of wood?  For that ski lodge effect, or to match that open fire... Lodge is the Furni of choice for Habbos with that no frills approach to decorating.  <br>', 'Click on the item you want for more information.', '2: I LOVE this wood Furni!', 0, FALSE, FALSE),
    (27, 27, 'Mode', 'Mode', 'ctlg_layout2', 'catalog_mode_headline1', 'catalog_mode_teaser1', 'Introducing the Mode Collection...  Steely grey functionality combined with sleek designer upholstery. The Habbo that chooses this furniture is a cool urban cat - streetwise, sassy and so slightly untouchable.', 'Click on the item you want for more information.', '2: So shiny and new...', 0, FALSE, FALSE),
    (29, 29, 'Plants', 'Plants', 'ctlg_layout2', 'catalog_plants_headline1', 'catalog_plants_teaser1', 'New, never before seen Bulrush Plant is here for a limited time only. Buy it now!<br>Introducing the Plant Collection...  Every room needs a plant! Not only do they bring a bit of the outside inside, they also enhance the air quality!', 'Click on the item you want for more information.', '2: I am at one with the trees', 0, FALSE, FALSE),
    (30, 30, 'Plastic', 'Plastic', 'ctlg_plasto', 'catalog_plasto_headline1', '', 'Introducing The Plastic Collection...  Can you feel that 1970s vibe?  Decorate with Plastic and add some colour to your life. Choose a colour that reflect your mood, or just pick your favourite shade.', 'Select an item and a colour and buy!', 'New colours!', 0, FALSE, FALSE),
    (31, 31, 'Presents', 'Presents', 'ctlg_presents', 'catalog_gifts_headline1', 'catalog_presents_teaser1,catalog_presents_teaser2', 'Show your Habbo friends just how much you care and send them a gift from the Habbo Catalogue.  ANY Catalogue item can be sent as a gift to ANY Habbo, all you need is their Habbo name!', '', '', 0, FALSE, FALSE),
    (32, 32, 'Pura', 'Pura', 'ctlg_layout2', 'catalog_pura_headline1', 'catalog_pura_teaser1', 'Introducing the Pura Collection...  This collection breathes fresh, clean air and cool tranquility. The Pura Waltzer has arrived!  Check back regularly to see  new colours of Pura on sale!', 'Click on the item you want for more information.', '', 0, FALSE, FALSE),
    (33, 33, 'Recycler', 'Ecotron', 'ctlg_recycler', 'catalog_recycler_headline1', '', '', '', '', 0, FALSE, FALSE),
    (34, 34, 'Rollers', 'Rollers', 'ctlg_layout2', 'catalog_roller_headline1', '', 'Move your imagination, while you move your Habbo!  Perfect for mazes, games, for keeping your queue moving or making your pet go round in circles for hours.  Available in multi-packs ? the more you buy the cheaper the Roller! Pink Rollers out now!', 'Click on a Roller to see more information!', 'You can fit 35 Rollers in a Guest Room!', 0, FALSE, FALSE),
    (35, 35, 'Romantique', 'Romantique', 'ctlg_layout2', 'catalog_romantique_headline1', 'catalog_rom_teaser', 'The Romantique range features Grand Pianos, old antique lamps and tables. It is the ideal range for setting a warm and loving mood in your room. Spruce up your room and invite that special someone over. Now featuring the extra special COLOUR edition.', 'Click on the item you want for more information.', '', 0, FALSE, FALSE),
    (36, 36, 'Rugs', 'Rugs', 'ctlg_layout2', 'catalog_rugs_headline1', 'catalog_rugs_teaser1', 'We have rugs for all occasions.  All rugs are non-slip and washable.', 'Click on the item you want for more information.', '2: Rugs, rugs and more rugs!', 0, FALSE, FALSE),
    (37, 37, 'Sports', 'Sport', 'ctlg_layout2', 'catalog_sports_headline1', 'catalog_sports_teaser1', 'For the sporty habbos, here is the sports section!', 'Click on the item you want for more information.', '', 0, FALSE, FALSE),
    (38, 38, 'Teleport', 'Teleport', 'ctlg_layout2', 'catalog_doors_headline1', 'catalog_teleports_teaser2,catalog_door_c,catalog_door_b', 'Beam your Habbo from one room to another with one of our cunningly disguised, space age teleports. Now you can link any two rooms together! Teleports are sold in pairs, so if you trade for them, check you''re getting a linked pair.', 'Select an item by clicking one of the icons on the left.', 'Teleport!', 0, FALSE, FALSE),
    (44, 44, 'Trophies', 'Trophies', 'ctlg_trophies', 'catalog_trophies_headline1', '', 'Reward your Habbo friends, or yourself with one of our fabulous glittering array of bronze, silver and gold trophies.<br><br>First choose the trophy model (click on the arrows to see all the different styles) and then the metal (click on the seal below the trophy). Type your inscription below and we''ll engrave it on the trophy along with your name and today''s date.', '', '', 0, FALSE, FALSE),
    (45, 45, 'Christmas', 'Christmas', 'ctlg_layout2', 'catalog_xmas_headline1', 'catalog_xmas_teaser', 'The Habbo Christmas catalogue has everything you need to make the perfect festive room: Trees, ducks with santa hats on, puddings and of course, Menorahs!', 'Click on an item to see a bigger version of it!', '2:Tuck into Christmas!', 0, FALSE, FALSE),
    (46, 46, 'Easter', 'Easter', 'ctlg_layout2', 'catalog_easter_headline1', 'catalog_easter_teaser1', '''Egg''cellent furni - Bouncing bunnies, fluffy chicks, choccy eggs... Yep, it''s Easter! Celebrate with something ''eggs''tra special from our Easter range. But hurry - it''s not here for long this year!', 'Click on an item for more details.', '2: ''Egg''-Tastic!', 0, FALSE, FALSE),
    (47, 47, 'Halloween', 'Halloween', 'ctlg_layout2', 'catalog_halloween_headline1', 'catalog_halloween_teaser', 'Yes, it''s a spookfest! Get your boney hands on our creepy collection of ghoulish goodies. But be quick - they''ll be gone from the Catalogue after two weeks!', 'Click on an item to see a bigger version of it!', '2:Halloween is My day!', 0, FALSE, FALSE),
    (48, 48, 'Love', 'Love', 'ctlg_layout2', 'catalog_love_headline1', 'catalog_love_teaser1', 'The love collection has everything to create the perfect love room, for a good price!', 'Click on an item to see a bigger version of it!', '2:Oh! Comes Valentine''s Day!', 0, FALSE, FALSE),
    (49, 49, 'Area Colour', 'Area Colour', 'ctlg_layout2', 'catalog_area_headline1', 'catalog_area_teaser1', 'Introducing the Area Collection...  Clean, chunky lines set this collection apart as a preserve of the down-to-earth Habbo. It''s beautiful in its simplicity, and welcoming to everyone.', 'Click on the item you want for more information.', 'Much More Colours!!!', 0, FALSE, FALSE),
    (50, 50, 'Iced Colour', 'Iced Colour', 'ctlg_layout2', 'catalog_iced_headline1', 'catalog_iced_teaser1', 'Introducing the Iced Collection...  For the Habbo who needs no introduction. It''s so chic, it says everything and nothing. It''s a blank canvas, let your imagination to run wild!', 'Click on the item you want for more information.', 'Much More Colours!!!', 0, FALSE, FALSE),
    (51, 51, 'Mode Colour', 'Mode Colour', 'ctlg_layout2', 'catalog_mode_headline1', 'catalog_mode_teaser1', 'Introducing the Mode Collection...  Steely grey functionality combined with sleek designer upholstery. The Habbo that chooses this furniture is a cool urban cat - streetwise, sassy and so slightly untouchable.', 'Click on the item you want for more information.', 'Much More Colours!!!', 0, FALSE, FALSE),
    (52, 52, 'Pura Colour', 'Pura Colour', 'ctlg_layout2', 'catalog_pura_headline1', 'catalog_pura_teaser1', 'Introducing the Pura Collection...  This collection breathes fresh, clean air and cool tranquility. The Pura Waltzer has arrived!  Check back regularly to see  new colours of Pura on sale!', 'Click on the item you want for more information.', 'Much More Colours!!!', 0, FALSE, FALSE),
    (53, 53, 'Romantique Colour', 'Romantique Colour', 'ctlg_layout2', 'catalog_romantique_headline1', 'catalog_rom_teaser', 'The Romantique range features Grand Pianos, old antique lamps and tables. It is the ideal range for setting a warm and loving mood in your room. Spruce up your room and invite that special someone over. Now featuring the extra special COLOUR edition.', 'Click on the item you want for more information.', 'Much More Colours!!!', 0, FALSE, FALSE),
    (54, 54, 'Club Furni', 'Club Furni', 'ctlg_layout2', 'catalog_club_headline1', 'catalog_hc_teaser', 'Welcome to the club furni page. Here you can buy any club furni for just 25 credits!', 'Click on an item to see more details', 'For Habbo Club members only!', 0, FALSE, TRUE),
    (56, 56, 'Dragons', 'Dragons', 'ctlg_layout2', 'catalog_jap_headline2', 'catalog_jap_teaser3', 'Here you can find the Power of Dragons! Get them now!', 'Click on the item you want for more information.', '1: All Colours!', 7, FALSE, FALSE),
    (57, 57, 'Fans', 'Fans', 'ctlg_layout2', 'catalog_rares_headline1', '', 'Hm... You have permission to stay here? Oh! if you don''t have permission, please go away!!!', 'Select a item, and see more details', 'Restricted Zone', 7, FALSE, FALSE),
    (58, 58, 'Ice Cream Rare', 'Ice Cream Rare', 'ctlg_layout2', 'catalog_rares_headline1', '', 'Hm... You have permission to stay here? Oh! if you don''t have permission, please go away!!!', 'Select a item, and see more details', 'Restricted Zone', 7, FALSE, FALSE),
    (59, 59, 'Inflatables', 'Inflatables', 'ctlg_layout2', 'catalog_rares_headline1', '', 'Hm... You have permission to stay here? Oh! if you don''t have permission, please go away!!!', 'Select a item, and see more details', 'Restricted Zone', 7, FALSE, FALSE),
    (60, 60, 'Laser Gates', 'Laser Gates', 'ctlg_layout2', 'catalog_rares_headline1', '', 'Hm... You have permission to stay here? Oh! if you don''t have permission, please go away!!!', 'Select a item, and see more details', 'Restricted Zone', 7, FALSE, FALSE),
    (61, 61, 'Marquee', 'Marquee', 'ctlg_layout2', 'catalog_rares_headline1', '', 'Hm... You have permission to stay here? Oh! if you don''t have permission, please go away!!!', 'Select a item, and see more details', 'Restricted Zone', 7, FALSE, FALSE),
    (62, 62, 'Monoliths', 'Monoliths', 'ctlg_layout2', 'catalog_rares_headline1', '', 'Hm... You have permission to stay here? Oh! if you don''t have permission, please go away!!!', 'Select a item, and see more details', 'Restricted Zone', 7, FALSE, FALSE),
    (63, 63, 'Oriental Screen', 'Oriental Screen', 'ctlg_layout2', 'catalog_rares_headline1', '', 'Hm... You have permission to stay here? Oh! if you don''t have permission, please go away!!!', 'Select a item, and see more details', 'Restricted Zone', 7, FALSE, FALSE),
    (64, 64, 'Pilars Rare', 'Pilars Rare', 'ctlg_layout2', 'catalog_rares_headline1', '', 'Hm... You have permission to stay here? Oh! if you don''t have permission, please go away!!!', 'Select a item, and see more details', 'Restricted Zone', 7, FALSE, FALSE),
    (65, 65, 'Pillow Rare', 'Pillow Rare', 'ctlg_layout2', 'catalog_rares_headline1', '', 'Hm... You have permission to stay here? Oh! if you don''t have permission, please go away!!!', 'Select a item, and see more details', 'Restricted Zone', 7, FALSE, FALSE),
    (66, 66, 'Smoke Machines', 'Smoke Machines', 'ctlg_layout2', 'catalog_rares_headline1', '', 'Hm... You have permission to stay here? Oh! if you don''t have permission, please go away!!!', 'Select a item, and see more details', 'Restricted Zone', 7, FALSE, FALSE),
    (67, 67, 'Summer Pools', 'Summer Pools', 'ctlg_layout2', 'catalog_rares_headline1', '', 'Hm... You have permission to stay here? Oh! if you don''t have permission, please go away!!!', 'Select a item, and see more details', 'Restricted Zone', 0, FALSE, FALSE),
    (68, 68, 'Rares', 'Rares', 'ctlg_layout2', 'catalog_rares_headline1', '', 'Hm... You have permission to stay here? Oh! if you don''t have permission, please go away!!!', 'Select a item, and see more details', 'Restricted Zone', 7, FALSE, FALSE),
    (69, 69, 'Trophies Rare', 'Trophies Rare', 'ctlg_trophies', 'catalog_trophies_headline1', '', 'Reward your Habbo friends, or yourself with one of our fabulous glittering array of bronze, silver and gold trophies.<br><br>First choose the trophy model (click on the arrows to see all the different styles) and then the metal (click on the seal below the trophy). Type your inscription below and we''ll engrave it on the trophy along with your name and today''s date.<br>', '', '', 7, FALSE, FALSE),
    (70, 70, 'Noob Edition', 'Noob Edition', 'ctlg_layout2', 'catalog_limited_headline1', 'catalog_limited_teaser1', 'Get it while its hot.. <br><br>LIMITED EDITION FURNITURE!', 'For a limited time only!', '', 0, FALSE, FALSE),
    (71, 71, 'Windows', 'Windows', 'ctlg_layout2', 'ctlg_windows_headline1', 'ctlg_windows_teaser1', 'Let some sunshine in! Our windows come in many styles to give an unique look to Your room. Who said Your room does not have a view? It does now', 'Click on an item to see more details', ' Ooh, new view!', 0, FALSE, FALSE),
    (72, 72, 'Ver. 18 to 20', 'Ver. 18 to 20', 'ctlg_layout2', 'catalog_limited_headline1', 'catalog_limited_teaser1', 'Get it while its hot.. <br><br>LIMITED EDITION FURNITURE!', 'For a limited time only!', '', 7, FALSE, FALSE),
    (73, 73, 'Ver. 21 to 23', 'Ver. 21 to 23', 'ctlg_layout2', 'catalog_limited_headline1', 'catalog_limited_teaser1', 'Get it while its hot.. <br><br>LIMITED EDITION FURNITURE!', 'For a limited time only!', '', 7, FALSE, FALSE),
    (74, 74, 'Tiki', 'Tiki', 'ctlg_layout2', 'catalog_tiki_header1', 'catalog_limited_teaser1', 'nieuwe meubi in de cata', 'Click on an item to see more details', ' Ooh, new view!', 0, FALSE, FALSE),
    (78, 78, 'Ver.24', 'Ver.24', 'ctlg_layout2', 'catalog_limited_headline1', 'catalog_limited_teaser1', 'nieuwe meubi in de cata', 'Click on an item to see more details', ' Ooh, new view!', 0, FALSE, FALSE),
    (79, 79, 'Advertisement', 'Advertisement', 'ctlg_layout2', 'catalog_limited_headline1', 'catalog_limited_teaser1', 'Get it while its hot.. <br><br>LIMITED EDITION FURNITURE!', 'For a limited time only!', '', 2, TRUE, FALSE),
    (80, 80, 'Greek', 'Greek', 'ctlg_layout2', 'catalog_limited_headline1', 'catalog_limited_teaser1', 'Get it while its hot.. <br><br>LIMITED EDITION FURNITURE!', 'For a limited time only!', '', 2, TRUE, FALSE);

